def quote_key(key: str) -> str:
    out = []
    for seg in key.split("/"):
        if seg in (".", ".."):
            out.append(seg.replace(".", "%2E"))
        else:
            out.append(quote(seg, safe="-_.~"))
    return "/".join(out)

